arguments.newString:
import os

def read_file(root: str, name: str):
    root_real = os.path.realpath(root)
    path_real = os.path.realpath(os.path.join(root, name))
    if os.path.commonpath([root_real, path_real]) != root_real:
        raise ValueError("path escapes root")
    with open(path_real) as f:
        return f.read()

